  const palette = number => ({'02':'dioda','03':'tranzistor','04':'tranzistor','05':'dioda','06':'signal','07':'filter','09':'signal','10':'signal','11':'signal','12':'dioda','13':'signal','14':'meter','15':'meter','16':'digital','17':'digital','18':'digital','19':'signal','20':'scope','21':'meter','22':'scope','23':'meter','24':'digital','25':'meter'})[number] || 'signal';
  const deep = {
    '04': [['Co je unipolární tranzistor','FET řídí proud mezi emitorem (source) S a kolektorem (drain) D, elektrickým polem hradla G. Proud v kanálu přenáší převážně jediný druh nosičů, proto unipolární. Vstupní proud hradla je u MOSFETu za ustáleného stavu velmi malý, protože jej odděluje izolant.'],['JFET a MOSFET','U JFETu řídí kanál závěrně polarizovaný přechod PN. U MOSFETu je hradlo odděleno dielektrikem: napětí UGS vytváří elektrické pole a mění vodivost kanálu. Rozliš obohacovací a ochuzovací princip; v běžné výkonové elektronice se používá hlavně obohacovací MOSFET.'],['N a P kanál','N-kanálový MOSFET se pro běžné nízkostranní spínání otevírá kladným UGS, P-kanálový záporným UGS. Směr šipky, zapojení S, G a D i dovolené polarity čti vždy z konkrétní značky a datasheetu; samotný tvar symbolu není náhradou mezních hodnot.'],['Charakteristiky','Výstupní charakteristika dává ID podle UDS při různých UGS. Převodní charakteristika ukazuje závislost ID na UGS. Hodnota VGS(th) není bezpečné „napětí pro plné sepnutí“: je definována jen pro malý zkušební proud. Pro spínač sleduj RDS(on) při daném UGS a teplotě.'],['MOSFET jako spínač','Vypnutý MOSFET blokuje proud, sepnutý má malý odpor RDS(on). Ztrátový výkon přibližně P = I²·RDS(on); při spínání přibývají ztráty v přechodu. Hradlo je kapacitní, proto budič musí dodat a odebrat náboj Qg rychle a kontrolovaně.'],['Ochrany a parazity','Indukční zátěž vyžaduje cestu pro proud po vypnutí, například volnoběžnou diodu u DC cívky. Sleduj maximální UGS, UDS, ID, ztrátový výkon, bezpečnou pracovní oblast a tepelný odpor. Nevhodné vedení hradla může způsobit kmitání nebo nechtěné sepnutí.'],['Praktické zapojení','Pro nízkostranní spínač je zdroj N-MOSFETu u země, zátěž mezi plus zdrojem a drainem. Gate má sériový odpor pro omezení špiček a pull-down, aby po resetu nezůstal otevřený. Společná zem řídicí a výkonové části se navrhuje s ohledem na proudové cesty.'],['Měření','Multimetrem ověříš zkraty G-S a G-D, ale funkci výkonového MOSFETu hodnotíš i pod zátěží. Osciloskopem měř UGS a UDS proti správné referenci; pozor na uzemněnou svorku sondy. Změř teplotu, proud a úbytek napětí v sepnutém stavu.'],['Typické chyby','Nezaměňuj VGS(th) za napětí plného sepnutí, nepřipojuj hradlo napřímo na nevhodné napětí a nevynechávej ochranu indukční zátěže. Při spínání PWM řeš frekvenci, budič, rozptylové indukčnosti a oteplení.'],['Maturita nanečisto','Začni principem FETu, porovnej JFET a MOSFET, zakresli N-MOSFET v nízkostranním spínači, vysvětli RDS(on), Qg a ztráty. Uzavři ochranou cívky, měřením UGS/UDS a bezpečným návrhem.']],
    '10': [['Úloha výkonového zesilovače','Výkonový zesilovač předává energii z napájecího zdroje do zátěže. Nehodnotí se jen napěťové zesílení, ale výstupní výkon, účinnost, zkreslení, impedanční přizpůsobení, stabilita a teplota.'],['Třídy A, B, AB a D','Třída A vede po celý průběh a má nízké zkreslení, ale malou účinnost. Třída B používá dvojici prvků pro půlperiody a trpí přechodovým zkreslením. AB nastaví malý klidový proud. D používá rychlé spínání a filtr, proto může mít vysokou účinnost.'],['Komplementární výstup','Push-pull stupeň používá NPN a PNP, případně N a P MOSFET, aby jedna větev dodávala a druhá odebírala proud. Správné předpětí určuje pracovní bod a omezuje přechodové zkreslení; přílišné předpětí však zvyšuje klidovou ztrátu.'],['Výkon a účinnost','Pro sinus do odporové zátěže platí P = Uef·Ief = Uef²/Rz. Účinnost η = Pout/Pin·100 %. Ztráty se mění v teplo, proto se stanoví ztrátový výkon tranzistoru, tepelný odpor a potřebný chladič.'],['Zkreslení','Harmonické zkreslení THD popisuje přídavné harmonické složky. Přechodové zkreslení je patrné kolem nuly u nedostatečně předpjaté třídy B. Limitace vzniká, když výstup nedosáhne žádaného napětí nebo proudu.'],['Zpětná vazba a stabilita','Záporná zpětná vazba může snížit zkreslení a výstupní odpor, ale musí být stabilní i s reaktivní zátěží. Reproduktor není čistý rezistor; má impedanční průběh. Výstupní ochrany a kompenzace se proto nenavrhují „od oka“.'],['Tepelný návrh','Použij vztah Tj = Ta + Pztr·RθJA nebo řetězec pouzdro–izolant–chladič–okolí. Zkontroluj maximální teplotu přechodu a derating. Chladič není dekorace: jeho montáž, pasta, proudění vzduchu a izolace ovlivňují výsledek.'],['Ochrany','Proudové omezení, tepelná ochrana, ochrana proti DC napětí na zátěži a zpožděné připojení reproduktoru chrání součástky i uživatele. U síťově napájeného zařízení odděl nízkonapěťovou část a respektuj bezpečnostní vzdálenosti.'],['Měření','Měř výstup do vhodné umělé zátěže, ne rovnou do citlivého reproduktoru. Osciloskopem sleduj limitaci a překmity, multimetrem Uef, případně analyzátorem THD. Teplotu kontroluj při dlouhodobé zátěži.'],['Maturita nanečisto','Porovnej třídy A/B/AB/D, nakresli komplementární push-pull, odvoď výkon do odporu a vysvětli účinnost, přechodové zkreslení, tepelné ztráty a ochrany.']],
    '11': [['Ideální operační zesilovač','Operační zesilovač má neinvertující vstup +, invertující vstup −, výstup a napájení. Ideálně má nekonečné otevřené zesílení, nekonečný vstupní odpor a nulový výstupní odpor; v reálném obvodu platí konečné meze.'],['Záporná zpětná vazba','Záporná vazba vrací část výstupu na invertující vstup a určuje přesné uzavřené zesílení odpory. Pokud pracuje lineárně a není na limitu, rozdílové napětí mezi vstupy je malé; neznamená to, že vstupy jsou fyzicky propojené.'],['Invertující zapojení','Vstup vede přes R1 do invertujícího vstupu, zpětná vazba přes R2. Pro ideální případ Au = −R2/R1. Neinvertující vstup je na referenci a uzel invertujícího vstupu je virtuální zem jen tehdy, když je referencí skutečně zem.'],['Neinvertující zapojení','Signál je na neinvertujícím vstupu, dělič R1/R2 přivádí vazbu na invertující vstup. Au = 1 + R2/R1. Zapojení neinvertuje fázi a má vysoký vstupní odpor, ale neporušuje výstupní proudové ani napěťové limity OZ.'],['Sčítání, rozdíl a integrace','Odpory umožní sčítání vstupů, diferenciální zapojení měří rozdíl. Kondenzátor ve zpětné vazbě vytvoří integrátor; kondenzátor na vstupu diferenciátor. Reálné obvody potřebují omezení zesílení na vysokých kmitočtech a vhodné počáteční podmínky.'],['Komparátor','Bez záporné vazby se OZ může použít jako komparátor, ale pro rychlé spínání je obvykle vhodnější specializovaný komparátor. Hystereze přes kladnou vazbu brání kmitání kolem prahu při šumu.'],['Reálné parametry','Sleduj napájecí rozsah, common-mode rozsah vstupů, výstupní rozkmit, maximální proud, rychlost přeběhu SR, GBW, vstupní offset a bias proudy. Rail-to-rail je vlastnost konkrétního vstupu či výstupu, ne automatická vlastnost každého OZ.'],['Stabilita','Kapacitní zátěž a nevhodná zpětná vazba mohou snížit fázovou rezervu a způsobit kmitání. Zkontroluj datasheet, rozvazovací kondenzátory u napájení a oscilační průběh bez i se zátěží.'],['Měření','Ověř napájení, stejnosměrný pracovní bod a teprve potom malé střídavé signály. Osciloskopem sleduj limitaci, rychlost přeběhu a kmitání; generátor nastavuje zdroj signálu.'],['Maturita nanečisto','Nakresli invertující i neinvertující OZ, odvoď jejich zesílení, vysvětli virtuální zem a roli záporné vazby. Doplň integrátor, komparátor s hysterezí a limity reálného obvodu.']],
    '12': [['Úloha napájecího zdroje','Zdroj převádí dostupnou elektrickou energii na napětí a proud požadovaný zátěží. Kromě hodnoty napětí se hodnotí stabilita, zvlnění, účinnost, elektromagnetická kompatibilita, ochrany a bezpečné galvanické oddělení.'],['Blokové schéma lineárního zdroje','Síťový transformátor snižuje střídavé napětí a odděluje síť. Usměrňovač vytvoří pulzující stejnosměrné napětí, filtr sníží zvlnění a stabilizátor drží výstup. Každý blok má ztráty a mezní hodnoty.'],['Transformátor','Pro ideální transformátor platí U1/U2 = N1/N2 = I2/I1. Přenáší střídavou energii magnetickou indukcí, nemění kmitočet a může galvanicky oddělit obvody. Skutečný transformátor má ztráty ve vinutí a jádře i úbytek napětí při zatížení.'],['Usměrnění','Jednocestný usměrňovač využívá jednu půlperiodu, dvoucestný obě. Graetzův můstek vede v každé půlperiodě přes dvě diody; zátěží teče proud stále stejným směrem. Dimenzuj závěrné napětí, proud a ztrátový výkon diod.'],['Filtrace a zvlnění','Kondenzátor se nabíjí u špiček a mezi nimi dodává energii zátěži. Přibližně ΔU = I/(f·C), kde f je kmitočet zvlnění; u dvoucestného usměrnění je dvojnásobný proti síťovému kmitočtu. Vyšší C sníží zvlnění, ale zvýší nabíjecí špičky.'],['Lineární stabilizátor','Lineární stabilizátor ztrácí výkon přibližně Pztr = (Uin−Uout)·Iout. Výhodou je jednoduchost a malé rušení, nevýhodou účinnost a teplo při velkém rozdílu napětí. Potřebuje správné vstupní/výstupní kondenzátory dle datasheetu.'],['Spínaný zdroj','Spínaný zdroj převádí energii rychlým spínáním, indukčností nebo transformátorem a zpětnou vazbou. Bývá účinnější a menší, ale vyžaduje řízení rušení, správné rozložení spojů, filtry a bezpečný návrh.'],['Ochrany a bezpečnost','Pojistka chrání vedení, ne nutně každou součástku. Používají se proudové, tepelné, přepěťové a zkratové ochrany. Síťové části patří jen do odborně navržených konstrukcí; měření na síti má zvláštní pravidla a vhodné přístroje.'],['Měření','Měř napětí naprázdno i při zatížení, zvlnění osciloskopem při správném nastavení sondy, proud sériově nebo proudovou sondou a teplotu kritických prvků. Zvlášť sleduj špičkový proud usměrňovače a oteplení stabilizátoru.'],['Maturita nanečisto','Nakresli blok lineárního zdroje, vysvětli transformátor, Graetzův můstek, filtraci a stabilizaci. Porovnej lineární a spínaný zdroj, dopočítej ztrátu stabilizátoru a uzavři ochranami i bezpečností.']]
  };
  const opampChapters = [
    ['Od diferenciálního stupně k OZ','Operační zesilovač začíná diferenciálním vstupem: zesiluje rozdíl napětí a potlačuje jejich společnou složku. Proudové zrcadlo vytváří aktivní zátěž a téměř konstantní proud. Další stupeň zvětší napěťové zesílení a výstupní stupeň dodá proud zátěži.'],
    ['Bloková algebra','Blok popisuje přenos <i>A</i> = výstup/vstup. V sérii se přenosy násobí, v paralelních větvích se výstupy podle znamének sčítají. Blokové schéma platí jen při zanedbatelném zpětném ovlivnění sousedních bloků.'],
    ['Zpětná vazba','Část výstupu se přes vazební člen β vrací na vstup. Pro zápornou vazbu platí <i>A</i><sub>ZF</sub> = <i>A</i><sub>0</sub>/(1 + β<i>A</i><sub>0</sub>), pro kladnou 1 − β<i>A</i><sub>0</sub> ve jmenovateli. Záporná vazba stabilizuje zesílení; kladná podporuje překlápění nebo kmitání.'],
    ['Čtyři typy záporné vazby','Podle snímání výstupu a způsobu vracení rozlišujeme napěťovou sériovou, napěťovou paralelní, proudovou sériovou a proudovou paralelní vazbu. Série na vstupu zvyšuje vstupní impedanci, paralelní připojení ji snižuje; napěťové snímání snižuje výstupní impedanci.'],
    ['Frekvenční charakteristika','Otevřené zesílení OZ s kmitočtem klesá. Záporná vazba zmenší zesílení, ale rozšíří použitelné pásmo. Součin zesílení a šířky pásma bývá u napěťově zpětnovazebních OZ přibližně konstantní; konkrétní mez určuje GBW a stabilita zapojení.'],
    ['Značka a ideální model','Značka má neinvertující vstup +, invertující vstup −, výstup a napájecí vývody. Ideální OZ má nekonečné otevřené zesílení a vstupní odpor, nulový výstupní odpor, nulový offset a neomezené pásmo. Tato pravidla jsou model, ne vlastnosti skutečné součástky.'],
    ['Převodní charakteristika a saturace','Bez zpětné vazby platí <i>U</i><sub>out</sub> = <i>A</i><sub>0</sub>(<i>U</i><sub>+</sub> − <i>U</i><sub>−</sub>), ale výstup narazí na kladnou nebo zápornou saturaci. Lineární oblast rozdílového napětí je kvůli velkému <i>A</i><sub>0</sub> velmi úzká.'],
    ['Reálné parametry OZ','Sleduj napájecí rozsah, vstupní common-mode rozsah, výstupní rozkmit a proud, vstupní offset, bias proudy, CMRR, PSRR, šum, GBW a rychlost přeběhu SR = Δ<i>U</i>/Δ<i>t</i>. Rail-to-rail musí být výslovně uvedeno pro vstup, výstup nebo obojí.'],
    ['Komparátor a hystereze','Komparátor porovnává vstupy a překlápí výstup mezi mezními úrovněmi. Kladná zpětná vazba vytvoří dvě různé spínací úrovně, tedy hysterezi, která brání kmitání při pomalém nebo zašuměném vstupu. Pro rychlé spínání se používá specializovaný komparátor.'],
    ['Invertující zesilovač','Proud přes <i>R</i><sub>1</sub> teče do uzlu invertujícího vstupu a přes <i>R</i><sub>2</sub> do výstupu; do vstupu OZ ideálně neteče. Pro zápornou vazbu platí <i>A</i><sub>u</sub> = −<i>R</i><sub>2</sub>/<i>R</i><sub>1</sub>. Virtuální zem vzniká jen tehdy, je-li neinvertující vstup na zemi.'],
    ['Neinvertující zesilovač a sledovač','U neinvertujícího zapojení je <i>A</i><sub>u</sub> = 1 + <i>R</i><sub>2</sub>/<i>R</i><sub>1</sub>. Napěťový sledovač vrací celý výstup na invertující vstup a má zesílení 1; používá se jako impedanční převodník mezi zdrojem a zátěží.'],
    ['Sčítací zesilovač','Více vstupů vede přes samostatné odpory do invertujícího uzlu. Výstup je vážený součet: <i>U</i><sub>out</sub> = −<i>R</i><sub>f</sub>Σ(<i>U</i><sub>k</sub>/<i>R</i><sub>k</sub>). Stejné odpory dávají prostý invertovaný součet; různé odpory určují váhy.'],
    ['Rozdílový a přístrojový zesilovač','Rozdílový zesilovač zesiluje <i>U</i><sub>2</sub> − <i>U</i><sub>1</sub>, pokud jsou poměry odporů přesně shodné. Přístrojový zesilovač přidává vstupní buffery, vysokou vstupní impedanci a vysoké potlačení souhlasného signálu; používá se pro malé signály ze snímačů.'],
    ['Integrátor','Kondenzátor ve zpětné vazbě dává <i>U</i><sub>out</sub> = −1/(<i>R C</i>)∫<i>U</i><sub>in</sub>d<i>t</i>. Konstantní vstup vytvoří lineární rampu. Reálný integrátor má paralelní odpor, který omezuje stejnosměrné zesílení a zabraňuje odplutí výstupu do saturace.'],
    ['Derivátor','Kondenzátor na vstupu a odpor ve vazbě dávají <i>U</i><sub>out</sub> = −<i>R C</i>·d<i>U</i><sub>in</sub>/d<i>t</i>. Hrana obdélníku vytvoří impulsy. Ideální derivátor silně zesiluje vysokofrekvenční šum, proto se praktické zapojení kmitočtově omezuje.'],
    ['Exponenciální a logaritmický zesilovač','Nelineární VA charakteristika diody nebo přechodu B-E převádí napětí na exponenciální proud. Výměnou nelineárního prvku mezi vstupem a vazbou vzniká logaritmický nebo exponenciální převod; platnost omezuje teplota, pracovní rozsah a předpoklad <i>A</i><sub>0</sub> → ∞.']
  ];
  const fetChapters = [
    ['Princip tranzistoru řízeného polem','FET (Field Effect Transistor) řídí proud vodivým kanálem elektrickým polem hradla G. Mezi elektrodami source S a drain D se pohybují převážně nosiče jednoho typu, proto se označuje jako unipolární. Řídicí vstup odebírá jen zanedbatelný ustálený proud.'],
    ['Dva způsoby řízení kanálu','U JFETu se průřez kanálu mění rozšiřováním ochuzené oblasti závěrně polarizovaného přechodu PN. U MISFETu, nejčastěji MOSFETu, je hradlo oddělené izolantem a elektrické pole mění koncentraci nosičů v kanálu.'],
    ['JFET: stavba a funkce','Kanál typu N nebo P spojuje S a D. Závěrné napětí mezi G a S kanál zužuje; při závěrném napětí U<sub>GS(off)</sub> se prakticky uzavře. Přechodem hradla se běžně nesmí téct propustný proud.'],
    ['MOSFET s indukovaným kanálem','Obohacovací MOSFET je při U<sub>GS</sub> = 0 vypnutý. Po překročení prahového napětí vznikne pod izolantem inverzní kanál. U N-kanálu jej vytváří kladné U<sub>GS</sub>, u P-kanálu opačná polarita.'],
    ['MOSFET s vodivým kanálem','Ochuzovací MOSFET má kanál vodivý už při U<sub>GS</sub> = 0. Napětí jedné polarity jej ochuzuje a zavírá, opačná polarita jej obohacuje. Ve značce se proto kanál kreslí plnou čarou.'],
    ['Přehled typů a značek','Rozliš JFET a MOSFET, N/P kanál a u MOSFETu indukovaný nebo vodivý kanál. Izolované hradlo vyjadřuje mezera ve značce. Vestavěná dioda výkonového MOSFETu není univerzální ochranná dioda pro každé zapojení.'],
    ['Výstupní charakteristiky','Graf I<sub>D</sub> = f(U<sub>DS</sub>) se kreslí pro několik U<sub>GS</sub>. V ohmické oblasti se kanál chová jako řízený odpor; v oblasti saturace je proud přibližně určen U<sub>GS</sub>. Mezní oblast znamená překročení dovoleného výkonu nebo napětí.'],
    ['Převodní charakteristika','Graf I<sub>D</sub> = f(U<sub>GS</sub>) ukazuje řízení proudu hradlem. U MOSFETu není U<sub>GS(th)</sub> napětí plného sepnutí: výrobce je udává při malém zkušebním proudu. Pro spínač se vybírá podle R<sub>DS(on)</sub> při konkrétním U<sub>GS</sub>.'],
    ['FET jako spínač','N-MOSFET v nízkostranním zapojení má S u země a zátěž mezi napájením a D. Gate rezistor omezuje proudovou špičku při nabíjení hradla a pull-down drží tranzistor vypnutý při resetu. Indukční zátěž potřebuje cestu pro dobíhající proud.'],
    ['Mezní hodnoty a zkoušková odpověď','Uveď U<sub>DS,max</sub>, U<sub>GS,max</sub>, I<sub>D</sub>, R<sub>DS(on)</sub>, ztrátový výkon, náboj hradla a teplotu přechodu. U maturity postupuj: princip pole → JFET/MOSFET → typy kanálů → charakteristiky → spínač → ochrany.']
  ];
  const powerAmpChapters = [
    ['Výkonový zesilovač a jeho třídy','Výkonový stupeň dodává energii ze zdroje do zátěže. Třídy A, B, AB a C se rozlišují pracovním bodem a úhlem otevření; G a H mění napájecí napětí. D a další spínací třídy převádějí signál na impulsy.'],
    ['Třída A: pracovní bod','Prvek vede celých 360°. Pracovní bod leží přibližně uprostřed zatěžovací přímky, takže lze zesílit obě půlperiody bez přechodového zkreslení. Klidový proud však teče i bez signálu a zahřívá tranzistor.'],
    ['Třída A: výkon a účinnost','Pro odporově vázaný stupeň ze skript vychází maximální teoretická účinnost 25 %. Není to obecná hodnota pro každé zapojení třídy A; transformátorová vazba může mít jinou mez. Výstupní výkon je P<sub>out</sub> = U<sub>ef</sub>²/R<sub>Z</sub>.'],
    ['Třída B','Každý tranzistor vede 180° a komplementární dvojice skládá obě půlperiody. Klidový proud je ideálně nulový, ale kolem průchodu nulou vzniká přechodové zkreslení. Ideální maximální účinnost je η<sub>max</sub> = π/4 ≈ 78,5 %.'],
    ['Třída AB','Oba prvky dostanou malé předpětí a vedou o něco déle než 180°. Tím se potlačí přechodové zkreslení třídy B, ale vznikne klidový proud. Teplotně nestabilní předpětí může vést k tepelnému úniku.'],
    ['Komplementární push-pull','Horní prvek dodává proud při kladné půlperiodě a dolní jej odebírá při záporné. Emitorové nebo source odpory pomáhají sdílení proudu a stabilitě. Reproduktor je reaktivní zátěž, ne pouhý rezistor.'],
    ['Třída C','Úhel otevření je menší než 180°. Proud má podobu impulsů a samotný stupeň silně zkresluje; laděný rezonanční obvod obnoví požadovanou sinusovou složku. Používá se hlavně ve vysokofrekvenčních zesilovačích.'],
    ['Třída G','Zesilovač má několik napájecích úrovní. Pro malý signál používá nižší napětí, při špičce se přepne na vyšší větev. Snižuje ztráty oproti AB s jediným vysokým napájením, ale přidává přepínací obvody.'],
    ['Třída H','Napájecí napětí sleduje obálku signálu plynule nebo po krocích. Rozdíl napětí na výkonovém prvku zůstává menší, a proto klesají ztráty. Návrh je složitější kvůli rychlosti sledování a rušení zdroje.'],
    ['Třída D: PWM princip','Vstupní audio se porovnává s vysokofrekvenčním trojúhelníkem. Komparátor vytvoří PWM, výkonové tranzistory spínají a dolní propust oddělí užitečnou nízkofrekvenční složku pro reproduktor.'],
    ['Třída D: ztráty a filtr','V ideálním sepnutí je na tranzistoru malé napětí nebo jím neteče proud, proto se účinnost blíží 100 %. Reálně ji snižuje R<sub>DS(on)</sub>, přechodové děje, náboj hradla a mrtvá doba. LC filtr se volí nad akustickým pásmem.'],
    ['Další spínací třídy','Označení I, T, E a F popisují různé spínací nebo rezonanční principy; jejich význam se může mezi výrobci lišit. U maturity je podstatné bezpečně vysvětlit A, B, AB, C, G, H a D a nezaměnit marketingový název za univerzální normu.'],
    ['Měření, chlazení a ochrany','Změř výkon do umělé zátěže, limitaci, THD a teplotu. Platí η = P<sub>out</sub>/P<sub>in</sub> a ztracený výkon se mění v teplo. Doplň proudové omezení, tepelnou ochranu a ochranu reproduktoru proti DC napětí.']
  ];
  const sourceChapters = [
    ['Rozdělení elektronických zdrojů','Podle vstupu a výstupu rozliš AC/AC měnič, DC/DC měnič, AC/DC zdroj a DC/AC střídač. Každý převádí napětí, proud nebo kmitočet; galvanické oddělení není automatické.'],
    ['Lineární a spínaný AC/DC zdroj','Klasický zdroj řadí transformátor, usměrňovač, filtr a stabilizátor. Spínaný zdroj nejprve usměrní síť, energii převádí vysokým kmitočtem a zpětnou vazbou. Je menší a účinnější, ale náročnější na rušení a bezpečnost.'],
    ['Transformátor','Ideálně platí U<sub>1</sub>/U<sub>2</sub> = N<sub>1</sub>/N<sub>2</sub> = I<sub>2</sub>/I<sub>1</sub>. Transformátor mění střídavé napětí a může galvanicky oddělit obvody; stejnosměrné napětí bez spínání nepřenáší.'],
    ['Jednocestný usměrňovač','Jedna dioda propustí jen jednu půlperiodu. Kmitočet zvlnění je stejný jako kmitočet sítě, využití transformátoru je malé a filtrační kondenzátor se vybíjí dlouho. Zapojení se hodí jen pro malé výkony.'],
    ['Dvoucestný usměrňovač se středem','Dvě diody střídavě využívají poloviny sekundárního vinutí se středním vývodem. Zátěží teče proud stejným směrem a kmitočet zvlnění je dvojnásobný. Každá dioda však musí snést vyšší závěrné napětí.'],
    ['Graetzův můstek','Čtyři diody vedou vždy po dvojicích. Není potřeba střed sekundáru a využijí se obě půlperiody; v proudové cestě jsou ale dva propustné úbytky. Důležité je umět vyznačit proud v obou půlperiodách.'],
    ['Třífázový můstek','Šest diod vybírá v každém okamžiku nejkladnější a nejzápornější fázi. Výstup má šest pulsů za periodu, menší zvlnění a je vhodný pro vyšší výkony. Pořadí fází nemění stejnosměrnou polaritu můstku.'],
    ['Kapacitní filtr a zvlnění','Kondenzátor se nabíjí u vrcholů a mezi nimi napájí zátěž. Přibližně ΔU ≈ I/(f<sub>zvlnění</sub>C). Větší C zmenší zvlnění, ale zvětší nabíjecí proudové špičky v diodách a transformátoru.'],
    ['RC, LC a π filtry','RC článek je jednoduchý, ale ztrácí napětí a výkon. Tlumivka brání změnám proudu a LC filtr má menší stejnosměrné ztráty. π filtr skládá C–L–C nebo C–R–C; návrh musí zohlednit rezonanci a zatížení.'],
    ['Parametrický stabilizátor se Zenerovou diodou','Sériový odpor omezuje proud a Zenerova dioda pracuje v závěrné průrazné oblasti. Zátěžová přímka určí pracovní bod. Proud diodou musí zůstat mezi minimem pro stabilizaci a maximem daným ztrátovým výkonem.'],
    ['Tranzistorový a zpětnovazební stabilizátor','Sériový tranzistor převezme proud zátěže a referenční napětí určuje výstup. Zpětnovazební stabilizátor porovnává část U<sub>out</sub> s referencí, zesílí regulační odchylku a řídí výkonový člen.'],
    ['Integrované stabilizátory','Řady 78xx a 79xx dávají pevné kladné a záporné napětí; potřebují rezervu vstupního napětí a doporučené kondenzátory. LM723 obsahuje referenci, zesilovač chyby a proudové omezení a lze jej doplnit externím výkonovým tranzistorem.'],
    ['Princip PWM regulace','Regulační odchylka mění střídu impulsů porovnáním řídicího napětí s pilovitým nebo trojúhelníkovým průběhem. LC prvek impulsy zprůměruje. Zpětná vazba udržuje výstup při změně vstupu i zátěže.'],
    ['Buck – snižující měnič','Při sepnutí ukládá tlumivka energii a napájí zátěž, při vypnutí pokračuje proud přes diodu nebo synchronní tranzistor. Ideálně v ustáleném spojitém režimu platí U<sub>out</sub> = D·U<sub>in</sub>.'],
    ['Boost – zvyšující měnič','Při sepnutí roste proud tlumivkou, při vypnutí se její napětí přičte ke vstupu a energie teče přes diodu do výstupu. Ideálně U<sub>out</sub> = U<sub>in</sub>/(1−D); vstupní proud nelze vypnout pouhým hlavním spínačem.'],
    ['Invertující buck-boost a Ćuk','Buck-boost může vytvořit výstup opačné polarity; ideálně U<sub>out</sub>/U<sub>in</sub> = −D/(1−D). Ćukův měnič přenáší energii vazebním kondenzátorem a má spojitější vstupní i výstupní proud, ale více prvků.'],
    ['Flyback a forward','Flyback ukládá energii do magnetizační indukčnosti a předává ji až po vypnutí spínače. Forward přenáší energii do sekundáru při sepnutí a potřebuje demagnetizaci jádra i výstupní tlumivku. Oba mohou galvanicky oddělovat.'],
    ['Push-pull, polomůstek a plný můstek','Push-pull střídavě budí dvě poloviny vinutí. Polomůstek přikládá na primár polovinu meziobvodového napětí, plný H-můstek celé napětí obou polarit. Nutná je mrtvá doba, aby se jedna větev nepropojila nakrátko.'],
    ['Násobiče a spínané kondenzátory','Diodově-kondenzátorový násobič skládá špičková napětí, ale se zatížením roste zvlnění a klesá výstup. Nábojová pumpa přenáší energii spínaným kondenzátorem a hodí se pro malé proudy bez tlumivky.'],
    ['Měření a bezpečnost','Ověř napětí naprázdno i pod zátěží, zvlnění, účinnost a teplotu. Primární strana síťového zdroje je životu nebezpečná a běžná uzemněná osciloskopická sonda může vytvořit zkrat; praktické měření patří pod odborný dohled.']
  ];
